import {WORD_CASES,WORD_SOURCES} from './word-cases.js';
// Adaptaciones de los materiales locales. Los archivos originales no se distribuyen.
export const CASE_SOURCES={
 ...WORD_SOURCES,
 obligaciones:'Casos prácticos Obligaciones Contratos y sociedades.pptx',
 titulos:'Casos prácticos títulos de crédito.pptx',
 actividad:'Actividad Requisitos Pagaré.pdf + UNIDAD 2.docx'
};
const choice=(title,prompt,options,answer,hint,explanation)=>({type:'choice',title,prompt,options,answer,hint,explanation});
const multiple=(title,prompt,options,answer,hint,explanation)=>({type:'multi',title,prompt,options,answer,hint,explanation});
const number=(title,prompt,answer,unit,hint,explanation)=>({type:'number',title,prompt,answer,unit,hint,explanation});
const C=(id,title,topic,source,location,facts,revision,refs,steps,reflection,model,kind='case')=>({id,title,topic,source,location,facts,revision,refs,steps:steps.map((s,i)=>({...s,id:`${id}-${i+1}`})),reflection,model,kind});
export const EXTRA_CASES=[
C('cp01','El auto con una prenda no informada','Contratos','obligaciones','diapositiva 2',
'Juan compra a María un auto por 10.000 euros. Paga y recibe el vehículo. Después descubre que tenía un gravamen prendario que no le habían informado.',
'La diapositiva presenta resolución o rebaja como salidas generales. La actividad distingue la carga jurídica de un defecto material y exige verificar los requisitos del remedio.',[['ccc','arts. 961, 1033–1039 y 1044–1049']], [
choice('Ubicá el problema','¿Qué apareció después de la compra?',['Un deterioro del motor','Un derecho de garantía sobre el auto','Una deuda de Juan ajena a la compra'],1,'Una prenda es una garantía real.','El gravamen afecta la situación jurídica del vehículo; no es, por ese solo hecho, un vicio material.'),
multiple('Armá el análisis','¿Qué hechos conviene comprobar?',['Si la prenda existía al vender','Qué se informó o pactó sobre cargas','Si el auto tenía un color que le gustaba a Juan','Cómo afecta el gravamen al derecho adquirido'],[0,1,3],'Uní el defecto del título con la información y sus efectos.','La buena fe y el saneamiento requieren analizar la carga, su conocimiento y cómo afecta la adquisición.'),
choice('Elegí una conclusión','¿Qué respuesta evita prometer un remedio automático?',['Todo gravamen anula la venta','Juan debe pagar por segunda vez sin discutir','Hay que analizar saneamiento e incumplimiento para elegir un remedio procedente'],2,'Detectar un incumplimiento no decide por sí solo toda la solución.','La resolución por defectos del título tiene presupuestos específicos. Tampoco toda rebaja procede automáticamente bajo cualquier régimen.')],
'¿Cómo explicarías la diferencia entre una prenda oculta y una falla oculta del motor?',
'La prenda es una carga jurídica; una falla preexistente del motor es material. En ambos casos hay que verificar el régimen aplicable, los hechos y los requisitos del reclamo.'),
C('cp02','Ana y el préstamo vencido','Obligaciones','obligaciones','diapositiva 3',
'Ana presta 5.000 euros a Carlos, quien promete devolverlos en seis meses. El acuerdo consta por escrito. El plazo vence y Carlos no devuelve el dinero.',
'Se conserva la situación. El cálculo de capital se separa de los intereses y otros rubros que el enunciado no cuantifica.',[['ccc','arts. 724, 730, 886 y 1525–1527']], [
choice('Identificá la fuente','¿Qué genera la obligación de restituir?',['Un mutuo','Una donación','Un comodato de billetes individualizados'],0,'Importa devolver un equivalente de dinero.','El mutuo obliga a restituir igual cantidad de cosas de la misma especie y calidad.'),
number('Separá capital y accesorios','¿Cuánto capital debe restituir Carlos, sin calcular accesorios?',5000,'euros','Usá la cantidad prestada.','El capital es de 5.000 euros. No se calcula un total con intereses sin conocer sus reglas y períodos.'),
choice('Decidí el próximo paso','¿Qué puede reclamar Ana?',['Solo una disculpa','El cumplimiento, con los accesorios que correspondan','La propiedad automática de la casa de Carlos'],1,'Pensá en los efectos del crédito.','El acreedor puede utilizar los medios legales para obtener la prestación. No puede apropiarse de cualquier bien por su sola voluntad.')],
'Redactá un reclamo académico separando fuente, vencimiento y prestación.',
'Ana es acreedora de la restitución por el mutuo. El plazo venció y Carlos no pagó. Corresponde analizar el cumplimiento del capital y los accesorios procedentes.'),
C('cp03','La limpieza que no cumple lo pactado','Obligaciones','obligaciones','diapositiva 4',
'Empresa A contrata la limpieza de sus oficinas durante un año. En varias ocasiones, el proveedor no alcanza los estándares acordados.',
'El caso se usa para trabajar fuente contractual y cumplimiento de una prestación de hacer. La resolución requiere un incumplimiento de entidad suficiente y los recaudos aplicables.',[['ccc','arts. 730, 774, 961 y 1084–1088']], [
choice('Clasificá','La prestación de limpieza es principalmente…',['Dar dinero','No hacer','Hacer'],2,'Identificá la actividad que se prometió.','El proveedor debe realizar un servicio conforme a lo contratado.'),
multiple('Buscá evidencia','¿Qué sirve para analizar el incumplimiento?',['Estándares del contrato','Registro de fallas concretas','La mera antipatía hacia el proveedor','Reclamos y respuestas'],[0,1,3],'Compará lo debido con lo efectivamente realizado.','La prueba de los estándares y fallas permite justificar el reclamo. Las preferencias personales no reemplazan esa comparación.'),
choice('Elegí el remedio','¿Puede resolverse por cualquier detalle mínimo?',['No: deben verificarse gravedad y recaudos','Sí, siempre y sin requisitos','No existe resolución de contratos'],0,'No equipares toda falla con incumplimiento esencial.','Puede reclamarse cumplimiento y analizar daños. La resolución exige revisar los presupuestos legales y contractuales.')],
'¿Qué hecho te permitiría distinguir una falla aislada de un incumplimiento relevante?',
'Importan la reiteración, la gravedad, el efecto sobre el interés de Empresa A y las posibilidades de subsanar, según el contrato.'),
C('cp04','El vencimiento del 1 de abril','Obligaciones','obligaciones','diapositiva 5',
'Carlos debe pagar a Laura 3.000 euros el 1 de abril. No paga ese día ni durante los treinta días siguientes, pese a las comunicaciones de Laura.',
'Se conserva la fecha. Para esta actividad se supone que el pago podía hacerse durante todo el 1 de abril y no había pacto especial ni causa de eximición.',[['ccc','arts. 768 y 886–888']], [
choice('Marcá el disparador','¿Qué determina la mora, bajo estos supuestos?',['La llamada número treinta','El vencimiento del plazo sin pagar','La presentación de una demanda'],1,'Hay plazo expreso.','La regla del art. 886 es la mora por el transcurso del tiempo fijado para cumplir.'),
choice('Armá la línea temporal','Si podía pagar todo el 1 de abril, ¿desde cuándo quedó vencido el plazo?',['Desde el 1 de marzo','Recién el 1 de mayo','Desde el 2 de abril'],2,'Separá el día disponible para pagar del período posterior.','Con la hipótesis temporal aclarada, el retraso comienza el 2 de abril. No hay un mes de gracia por falta de demanda.'),
multiple('Separá consecuencias','¿Qué rubros deben distinguirse?',['Capital','Intereses moratorios procedentes','Cualquier gasto inventado por Laura','Otros daños o gastos solo si tienen fundamento'],[0,1,3],'No todo rubro mencionado es automáticamente exigible.','Capital, intereses y otros rubros tienen presupuestos propios; los gastos requieren fundamento y, cuando corresponde, prueba.')],
'¿Para qué sirven las llamadas si la mora ya era automática?',
'Pueden documentar intentos de cobro o facilitar una solución. No son el hecho constitutivo de la mora bajo la hipótesis del caso.'),
C('cp05','Calculá el interés de demora','Obligaciones','obligaciones','diapositiva 6',
'María presta a Pedro 5.000 euros. Vence el 1 de abril y se pacta un interés moratorio del 10% anual. Pedro no paga.',
'La diapositiva no indica cuántos días calcular. Se agrega una variante numérica: 30 días, interés simple y año de 365 días, sin capitalización.',[['ccc','arts. 768–771 y 886']], [
choice('Elegí la fórmula','Para esa variante, el interés se calcula como…',['Capital × tasa anual × días / 365','Capital × 10 × 365','Capital / días'],0,'La tasa anual debe convertirse al período.','Se aplica 5.000 × 0,10 × 30 / 365. No se usa 10 como si fuera una tasa de 1.000%.'),
number('Hacé la cuenta','¿Cuánto interés resulta, redondeado a dos decimales?',41.10,'euros','Primero calculá el interés anual: 500 euros.','500 × 30 / 365 = 41,09589… euros. Redondeado: 41,10. Es una convención didáctica, no una liquidación judicial.'),
choice('Detectá el límite','¿Los intereses se capitalizan automáticamente cada día?',['Sí, siempre','No: la capitalización tiene reglas y excepciones','Nunca existe capitalización'],1,'Revisá el art. 770.','No corresponde sumar intereses al capital sin verificar una hipótesis de capitalización admitida.')],
'Anotá qué datos faltaría pedir para una liquidación real.',
'Fechas y días efectivos, tasa aplicable, convención de cálculo, pagos parciales y eventual capitalización autorizada. El resultado de la variante no resuelve por sí solo una liquidación real.'),
C('cp06','¿No reclamar convierte en moroso al acreedor?','Obligaciones','obligaciones','diapositivas 7–8',
'Carlos presta 2.000 euros a María, con devolución el 1 de junio. María no paga y Carlos no reclama inmediatamente.',
'Corrección del material: las diapositivas atribuyen mora del acreedor a la inacción. El art. 886 exige una oferta de pago adecuada y una negativa injustificada a recibirla.',[['ccc','arts. 867 y 886']], [
choice('Detectá el error','¿La sola falta de reclamo de Carlos configura mora del acreedor?',['Sí, al día siguiente','No, esos hechos no bastan','Sí, si el préstamo es en euros'],1,'¿María ofreció un pago correcto que Carlos rechazó?','El enunciado no relata oferta de pago ni negativa de recepción. La falta de reclamo no equivale a mora del acreedor.'),
multiple('Completá el supuesto','¿Qué hechos permitirían analizar mora del acreedor?',['Oferta de pago conforme a lo debido','Negativa injustificada a recibirla','Simple silencio ante una deuda impaga','Voluntad interna de pagar sin ofrecer hacerlo'],[0,1],'El foco está en la cooperación necesaria para recibir el pago.','La oferta debe respetar las condiciones de pago. Pensar en pagar o esperar un reclamo no basta.'),
choice('Volvé a los hechos','Con plazo expreso y sin otras circunstancias, ¿de quién puede analizarse la mora?',['De Carlos por no llamar','De nadie porque no hay juicio','De María por no pagar al vencimiento'],2,'No inviertas acreedor y deudor.','El incumplimiento temporal es de María. Deben considerarse posibles excepciones o causas de eximición, no presumirlas.')],
'Corregí en dos frases la explicación de la diapositiva.',
'Carlos no incurre en mora por dejar de reclamar. Para mora del acreedor falta una oferta de pago conforme a derecho y su rechazo injustificado.'),
C('cp07','Un mes sin exigir el pago','Obligaciones','obligaciones','diapositiva 9',
'David presta a Laura 3.000 euros, a devolver el 1 de junio. No hay período de gracia. Laura no paga y transcurre un mes sin reclamo de David.',
'Corrección del material: la demora en reclamar no genera por sí sola mora del acreedor ni hace comenzar los intereses recién con el reclamo.',[['ccc','arts. 768 y 886–888']], [
choice('Elegí el hecho decisivo','¿Qué dato inicia el análisis de la mora de Laura?',['Que David esperó un mes','Que venció un plazo expreso sin pago','Que el préstamo tenía un nombre formal'],1,'El caso dice que no hay período de gracia.','La regla de mora automática se vincula al plazo de cumplimiento.'),
choice('Explicá los intereses','Los intereses moratorios compensan principalmente…',['La demora del deudor en pagar','La demora del acreedor en llamar','La falta de amistad entre las partes'],0,'Identificá quién incumple la prestación.','No son una compensación a David por su propia tardanza en reclamar. Su procedencia se analiza desde la mora del deudor.'),
choice('Cambiá un hecho','Variante: Laura ofrece pagar correctamente y David se niega sin motivo. ¿Qué cambia?',['Laura pasa a ser acreedora del préstamo','Se borra automáticamente toda la historia de la deuda','Ahora sí hay hechos para analizar mora del acreedor'],2,'La variante agrega cooperación frustrada para recibir el pago.','Es un hecho nuevo, ausente del caso original. Sus efectos deben analizarse desde que ocurre.')],
'¿Qué diferencia existe entre este caso y la variante final?',
'En el original solo hay falta de reclamo. En la variante hay oferta de pago correcta y rechazo injustificado: ese dato cambia el encuadre.'),
C('cp08','El televisor defectuoso','Contratos','obligaciones','diapositiva 10',
'María compra y paga un televisor en una tienda física. Recibe el equipo y un recibo. A los pocos días aparecen defectos y quiere reclamar la garantía.',
'Se trabaja el supuesto como una compra para uso personal a un proveedor. No se presume un derecho general de arrepentimiento por comprar en una tienda física.',[['ccc','arts. 1092–1094 y 1051–1058']], [
multiple('Ubicá las fuentes','¿Qué integra el marco de la obligación del vendedor?',['El contrato de compraventa','Las normas de protección del consumidor','Solo su voluntad de ayudar','Las garantías legales aplicables'],[0,1,3],'El contrato no actúa aislado de la ley.','La relación de consumo suma protección legal. La respuesta no depende solo de que el vendedor quiera reconocer el defecto.'),
choice('Elegí evidencia útil','¿Qué conviene conservar?',['Solo el envoltorio decorativo','Compra, entrega, falla y comunicaciones de reclamo','Ningún comprobante'],1,'Armá una historia verificable del problema.','Los comprobantes y registros ayudan a identificar producto, fechas, defecto y reclamos.'),
choice('Detectá una confusión','¿Compra presencial equivale a revocación libre automática durante diez días?',['No: esa regla corresponde a supuestos específicos, no a toda compra presencial','Sí, sin excepciones','Sí, pero solo si el televisor es grande'],0,'No confundas garantía por defecto con revocación de ciertas contrataciones.','María plantea un defecto y una garantía. Los contratos a distancia o fuera del establecimiento tienen reglas particulares de revocación.')],
'Separá en tu respuesta contrato, relación de consumo y defecto.',
'La compraventa origina prestaciones recíprocas. Por el destino personal y el proveedor, se aplica protección del consumidor. La falla exige analizar la garantía y los remedios correspondientes.'),
C('cp09','María recibe un préstamo de Luis','Obligaciones','obligaciones','diapositiva 11, supuesto 1',
'La presentación propone que María recibe un préstamo de su amigo Luis y pide identificar la fuente de la obligación. Para distinguir la figura, esta adaptación supone expresamente que se trata de dinero con obligación de devolverlo.',
'Es uno de los dos supuestos breves de la diapositiva 11. Las preguntas adicionales son una adaptación didáctica.',[['ccc','arts. 726 y 1525']], [
choice('Identificá','La fuente de la restitución es…',['Un contrato de mutuo','Un daño ilícito','El simple parentesco'],0,'Que sean amigos no elimina la figura contractual.','El préstamo de dinero con obligación de restitución se encuadra como mutuo.'),
choice('No confundas','¿La amistad convierte necesariamente el préstamo en donación?',['Sí','Solo si no hay banco','No'],2,'Importa si se asumió o no la restitución.','Una entrega con obligación de devolver no se transforma en donación por existir amistad.'),
choice('Buscá el dato','¿Qué información pedirías para analizar cuándo debe devolver?',['El plazo acordado y sus condiciones','El color del sobre','La profesión de un vecino'],0,'La fuente y la exigibilidad son preguntas distintas.','Conocer la existencia del contrato no fija por sí solo todos sus términos.')],
'¿Qué hecho separaría este préstamo de una donación?',
'La obligación de restitución. Si se acredita una entrega gratuita sin deber de devolver, cambia la figura que debe analizarse.'),
C('cp10','El daño causado por María','Obligaciones','obligaciones','diapositiva 11, supuesto 2',
'El segundo supuesto breve plantea que María realiza un acto ilícito que causa daño a otra persona.',
'No se añaden víctimas ni daños concretos. Se trabaja con la información que efectivamente ofrece la presentación.',[['ccc','arts. 1716–1717, 1721 y 1726']], [
choice('Identificá la fuente','La eventual obligación de indemnizar se vincula con…',['Un contrato de compraventa necesariamente','Responsabilidad civil por el daño','Una donación'],1,'La obligación puede surgir sin contrato previo.','El deber de reparar puede nacer de la violación del deber de no dañar.'),
multiple('Evitá automatismos','¿Qué debe analizarse para atribuir responsabilidad?',['Daño','Relación causal','Factor de atribución aplicable','Solo que alguien esté enojado'],[0,1,2],'Un resultado molesto no sustituye los presupuestos de responsabilidad.','Deben revisarse los presupuestos, la antijuridicidad y posibles causas de justificación o eximentes.'),
choice('Marcá el límite','¿El enunciado permite calcular una indemnización exacta?',['Sí: 1.000 euros','Sí: siempre el doble','No: faltan datos sobre el daño'],2,'No inventes montos ausentes.','La clasificación de la fuente no permite cuantificar un perjuicio que no se describe.')],
'¿Qué pedirías saber antes de calcular una reparación?',
'Qué daño ocurrió, cómo se conecta con el hecho, quién responde y cómo se acredita su extensión.'),
C('cp11','El dinero del jardín: ¿regalo o error?','Obligaciones','obligaciones','diapositiva 12',
'Ana ayuda a Pedro a renovar el jardín. El material dice que Pedro le entrega 1.000 euros como agradecimiento, pero luego afirma que fue un error y que no quiso entregárselos.',
'El relato contiene dos explicaciones incompatibles que no deben resolverse inventando hechos. La actividad hace explícita esa ambigüedad.',[['ccc','arts. 1542, 1794–1796']], [
choice('Detectá la ambigüedad','¿Qué dato necesita aclararse?',['Si el jardín tenía flores','Si hubo una entrega querida con causa o un pago indebido','Si Ana prefiere efectivo'],1,'“Como agradecimiento” y “por error” no son equivalentes.','Una liberalidad válida podría ser causa de la atribución. El relato no permite descartar esa posibilidad sin más.'),
choice('Rama 1','Si se prueba una donación válida y luego Pedro se arrepiente, ¿eso basta para afirmar enriquecimiento sin causa?',['Sí','No','Sí, si pasan dos días'],1,'Hay una causa jurídica que no desaparece por mero arrepentimiento.','La devolución no se funda automáticamente en enriquecimiento sin causa cuando existe una atribución válida.'),
choice('Rama 2','Si se prueba un pago no debido, ¿qué corresponde analizar?',['Restitución conforme al régimen de pago indebido','Que Ana siempre pueda conservarlo','Una pena automática contra Ana'],0,'La existencia de una acción específica importa.','Se analiza pago indebido. La acción de enriquecimiento sin causa tiene carácter subsidiario cuando hay otra acción disponible.')],
'Respondé el caso sin ocultar el dato contradictorio.',
'Primero aclararía si la entrega tenía una causa válida. Si la tenía, no corresponde tratarla sin más como enriquecimiento sin causa. Si fue un pago indebido, se analiza la restitución por ese régimen.'),
C('cp12','La penalidad de 2.000 euros','Contratos','obligaciones','diapositivas 13–14',
'Carlos alquila un local a Ana. Pactan una penalidad de 2.000 euros por incumplir o retrasarse en el alquiler. Tras tres meses impagos, Ana exige la penalidad y Carlos dice que es excesiva.',
'Se distingue una pena por retardo de otros supuestos y se explicitan los requisitos de reducción judicial. No se multiplican los 2.000 euros por mes sin una cláusula que lo diga.',[['ccc','arts. 790, 793–794 y 797']], [
choice('Identificá','¿Qué figura pactaron?',['Una cláusula penal','Una compensación legal','Una garantía prendaria'],0,'El contrato fija una prestación para el incumplimiento.','La cláusula penal procura asegurar el cumplimiento y determina una pena ante incumplimiento o retardo.'),
choice('Probá el argumento','¿Ana debe probar perjuicios para pedir la pena?',['Sí, siempre por exactamente 2.000','No, el art. 794 no exige esa prueba para pedirla','Solo si Carlos lo autoriza'],1,'Diferenciá la pena pactada de cuantificar daños.','Pedir la pena no exige probar perjuicios. Esto no impide controlar los presupuestos del pacto o un abuso.'),
choice('Decidí con matices','¿Cuál es la respuesta correcta a “es excesiva”?',['Toda pena se reduce a cero','Carlos puede decidir pagar la mitad','Cabe pedir reducción judicial si la desproporción y circunstancias configuran el supuesto legal'],2,'Revisá gravedad, valor de prestaciones y aprovechamiento abusivo.','El art. 794 admite reducción judicial bajo sus condiciones. No basta una preferencia subjetiva del deudor.')],
'¿Por qué no corresponde sumar automáticamente tres penalidades de 2.000?',
'El enunciado no establece una pena mensual. Hay que interpretar la cláusula, su hecho generador y la posibilidad de acumulación con la prestación por retardo.'),
C('cp13','Los dos pagos de Luis','Obligaciones','obligaciones','diapositivas 15–16',
'Luis debe a Marta 4.000 euros. En marzo entrega 2.000 y en julio otros 2.000. En agosto aparece una carta sobre la cancelación de la deuda.',
'El material cambia quién envía la carta: primero Luis, luego Marta. Para el ejercicio se supone que los pagos fueron recibidos e imputados al capital y no quedan accesorios pendientes.',[['ccc','arts. 865, 869–870 y 894–899']], [
number('Llevá el saldo','¿Qué capital queda después del pago de marzo?',2000,'euros','Restá 2.000 del capital inicial.','Queda la mitad del capital. Un pago parcial no extingue por sí solo todo el crédito.'),
choice('Elegí el momento','Bajo los supuestos aclarados, ¿cuándo se extingue la obligación por pago?',['En julio, con el pago restante','En agosto, solo por escribir una carta','En enero, al prometer pagar'],0,'La extinción deriva del cumplimiento.','Los pagos aceptados completan la prestación en julio. La carta cumple una función probatoria si corresponde.'),
choice('Detectá el error','¿Una carta unilateral de Luis diciendo “ya no debo” prueba por sí sola que pagó?',['Sí, siempre','No: hay que analizar la prueba del pago y quién reconoce la cancelación','Sí, si la envía en agosto'],1,'No confundas una afirmación propia con un recibo del acreedor.','El texto es inconsistente sobre el emisor. La afirmación del deudor no equivale sin más a un recibo o reconocimiento de la acreedora.')],
'Explicá qué cambia si había intereses pendientes.',
'No podría concluirse cancelación íntegra solo sumando capital. Habría que analizar imputación de pagos, accesorios y el alcance del recibo o reconocimiento.'),
C('cp14','Deudas cruzadas: 3.000 contra 2.000','Obligaciones','obligaciones','diapositiva 17',
'Ana debe a Pedro 3.000 euros por un préstamo. Pedro debe a Ana 2.000 euros por reparaciones. Ambos créditos están pendientes.',
'Para calcular, se agrega que los créditos son exigibles, disponibles, homogéneos, sin afectación de terceros ni exclusiones, y que se opone la compensación. Estar pendientes no basta por sí solo.',[['ccc','arts. 921–924 y 930']], [
choice('Identificá','¿Qué modo de extinción corresponde analizar?',['Confusión por tener dos contratos','Compensación de créditos recíprocos','Donación mutua obligatoria'],1,'Hay dos personas y dos créditos cruzados.','La compensación extingue hasta el monto menor cuando se cumplen sus presupuestos.'),
number('Calculá el saldo','Bajo los supuestos agregados, ¿cuántos euros sigue debiendo Ana a Pedro?',1000,'euros','3.000 menos 2.000.','Se compensan 2.000 en ambas deudas y Ana conserva un saldo de 1.000 a su cargo.'),
multiple('Chequeá requisitos','¿Qué hay que verificar antes de aplicar compensación legal?',['Exigibilidad','Homogeneidad de las prestaciones','Disponibilidad y derechos de terceros','Solo que los nombres se repitan'],[0,1,2],'El art. 923 agrega condiciones a la reciprocidad.','La reciprocidad no es el único requisito. También deben considerarse las exclusiones y la oposición prevista en el art. 924.')],
'¿Por qué el caso original no alcanza para hablar de compensación automática sin aclaraciones?',
'Decir que las deudas son válidas y pendientes no acredita todos los requisitos. Además, el art. 924 regula los efectos de la compensación una vez opuesta.'),
C('cp15','La herencia y la supuesta confusión','Obligaciones','obligaciones','diapositiva 18',
'Juan recibió de Luis un préstamo de 5.000 euros, luego le prestó otra suma y más tarde heredó una deuda familiar. El material concluye que existe confusión.',
'El relato no explica claramente que Juan haya adquirido el crédito contra sí mismo en un mismo patrimonio. Se conserva esa insuficiencia como problema para resolver.',[['ccc','arts. 921 y 931–932']], [
choice('Detectá el salto','¿Las deudas cruzadas entre Juan y Luis prueban por sí solas confusión?',['Sí','No: se debe distinguir de compensación','Sí, si valen lo mismo'],1,'Confusión exige reunir ambas posiciones de una misma obligación.','Dos obligaciones recíprocas pueden llevar a analizar compensación. No muestran que acreedor y deudor coincidan en una persona y patrimonio.'),
choice('Pedí el dato','¿Qué tendría que verificarse para aplicar el art. 931?',['Que ambos sean amigos','Que exista cualquier herencia','Que Juan reúna crédito y deuda de la misma obligación en un mismo patrimonio'],2,'La identidad del crédito importa más que la coincidencia del monto.','Heredar otra deuda no equivale a adquirir el crédito contra sí mismo. Tampoco deben ignorarse las reglas patrimoniales sucesorias.'),
choice('Cerrá con rigor','¿Qué conclusión permite el enunciado?',['Faltan datos para afirmar extinción por confusión','Toda deuda heredada extingue las propias','Siempre se debe pagar dos veces'],0,'No completes el relato con hechos inventados.','La figura está correctamente definida en abstracto, pero los hechos relatados no acreditan sin más sus presupuestos.')],
'¿Qué corregirías del análisis que acompaña al caso?',
'Pediría identificar el crédito concreto y cómo se reúnen sus posiciones en el mismo patrimonio. No deduciría confusión de préstamos cruzados ni de heredar una deuda distinta.'),
C('cp16','Marta y el auto con defectos ocultos','Contratos','obligaciones','diapositivas 19–20',
'Marta compra a Pedro un auto usado por 8.000 euros y paga al entregarse. Pedro promete buen estado. Luego Marta detecta defectos ocultos no informados.',
'La actividad evita presentar reparación, rebaja y resolución como opciones automáticas e indistintas. El régimen aplicable y los presupuestos del defecto importan.',[['ccc','arts. 959, 1039 y 1051–1057']], [
choice('Separá prestaciones','Respecto del auto en condiciones pactadas, ¿quién es deudor?',['Marta','Pedro','El banco de Marta necesariamente'],1,'Preguntá quién prometió esa entrega.','Pedro debe entregar conforme a lo pactado. Marta debe el precio: los roles cambian según la prestación.'),
multiple('Investigá el defecto','¿Qué datos sirven para analizar la garantía?',['Existencia al adquirir','Posibilidad de conocerlo mediante examen adecuado','Gravedad y posibilidad de subsanar','Solo el disgusto de Marta'],[0,1,2],'No todo problema posterior es un vicio preexistente.','La existencia, carácter oculto, gravedad y prueba son relevantes. También importan denuncia y plazos aplicables.'),
choice('Elegí una salida fundada','Si es subsanable, Pedro ofrece subsanarlo y Marta se niega, ¿puede resolver solo por ese defecto bajo el art. 1057?',['No, ese artículo impide resolver en ese supuesto','Sí, siempre','Sí, pero pagando doble'],0,'Leé completa la hipótesis del art. 1057.','En ese supuesto no corresponde resolver por el defecto. Queda a salvo la reparación de daños que proceda.')],
'Compará este auto con el caso de Juan y la prenda.',
'Acá se analiza un defecto material. En el otro caso hay una carga jurídica. No basta decir “problema oculto” para aplicar exactamente la misma solución.'),
C('cp17','El local cedido sin permiso','Contratos','obligaciones','diapositivas 21–22',
'Laura alquila un local por 1.000 euros mensuales durante un año. Necesita permiso del locador para ceder o subalquilar. Sin pedirlo, permite que una empresa vinculada ocupe el local y pague. Quedan meses adeudados.',
'Se conserva la distinción entre partes y terceros. Se añade la precisión de que puede existir acción directa contra un sublocatario bajo el art. 1216, si sus presupuestos se verifican.',[['ccc','arts. 1021–1022, 1213–1216 y 1636']], [
choice('Ubicá a la parte','¿Quién asumió inicialmente el pago frente al locador?',['Laura','Toda empresa vinculada','Cualquier ocupante del barrio'],0,'Identificá quién celebró el contrato.','Laura es la locataria original. No queda liberada automáticamente por hacer entrar a otra empresa.'),
choice('Evitá la confusión','¿Ocupar y pagar convierte automáticamente a la empresa en cesionaria válida?',['Sí','No: hay que analizar cesión, consentimiento y conducta de las partes','Sí, si pertenece a un familiar'],1,'La conducta puede ser relevante, pero no reemplaza todo el análisis.','Deben examinarse la figura utilizada, las autorizaciones y los hechos. Cesión y sublocación no son lo mismo.'),
choice('Probá la excepción','¿“Es tercero” significa que el locador nunca tiene acción contra la empresa?',['Sí, sin excepciones','Solo si nadie conserva el contrato','No: deben verificarse posibles acciones legales, como la del art. 1216'],2,'Hay efectos legales específicos más allá del principio general.','La acción directa contra el sublocatario tiene límites, incluida la medida de su deuda. No se presume aplicable sin comprobar el supuesto.')],
'Redactá una conclusión que no libere automáticamente a Laura ni condene automáticamente a la empresa.',
'Laura sigue vinculada por el contrato mientras no exista una sustitución eficaz. La responsabilidad de la empresa requiere analizar qué vínculo se creó y si existe una acción directa u otra base legal.'),
C('tc01','I, J y K: el pagaré que circula','Títulos de crédito','titulos','diapositiva 2',
'I emite un pagaré a favor de J. J lo endosa a K. El caso pregunta si K puede cobrar pese a defensas que I tiene contra J, y propone comparar buena y mala fe.',
'La devolución se ajusta al art. 18: para esa excepción personal importa adquirir a sabiendas en perjuicio del deudor. No se importan automáticamente criterios genéricos de otros países.',[['letras','arts. 17–18 y 103']], [
choice('Seguí el recorrido','¿Quién recibe el título por el endoso de J?',['I','K','Nadie hasta que I firme otra vez'],1,'El endosatario es el destinatario de la transmisión.','K recibe el título. Su legitimación exige revisar la cadena y las condiciones del instrumento.'),
choice('Elegí la regla','¿Una defensa personal contra J se opone automáticamente a K?',['No: rige la protección con sus excepciones','Sí, todas las defensas viajan siempre','Nunca puede oponerse ninguna defensa de ninguna clase'],0,'Distinguí defensas personales de otras excepciones.','El art. 18 limita la oposición de defensas personales relativas a tenedores anteriores. No elimina las defensas propias del título.'),
choice('Cambiá una condición','Si K adquirió a sabiendas en perjuicio de I, ¿qué debe analizarse?',['Que K cobre el doble','Que el pagaré desaparezca físicamente','La excepción a la inoponibilidad de defensas personales'],2,'El conocimiento perjudicial cambia la protección.','El art. 18 permite oponer esas excepciones bajo el supuesto legal. Su prueba y la vía procesal deben analizarse.')],
'¿Por qué no alcanza con decir “K tiene el papel, entonces siempre cobra”?',
'Además de la posesión importan legitimación, regularidad y defensas oponibles. La autonomía protege la circulación bajo condiciones, no vuelve infalible cualquier reclamo.'),
C('tc02','Diego, el endoso en blanco y la firma dudosa','Títulos de crédito','titulos','diapositivas 3–5',
'Marco firma un pagaré a favor de Bruno por 15.000. Bruno lo endosa a Carla y Carla firma un endoso en blanco para entregárselo a Diego. Marco no paga. Ana, mencionada también en el relato, sospecha que la firma de Bruno es falsa.',
'El original introduce a Ana sin aclarar su papel. Se trabaja con Diego como portador descripto. Un endoso en blanco no cambia la naturaleza del pagaré a un título emitido al portador. La sospecha no se toma como falsedad probada.',[['letras','arts. 7, 15–18, 46–57 y 103–104']], [
choice('Identificá al legitimado','Con una cadena formal regular y la tenencia descripta, ¿quién aparece para reclamar?',['Ana solo por sospechar','Diego','Bruno necesariamente aunque ya lo entregó'],1,'Seguí el último endoso y la tenencia.','Diego aparece como portador legitimado. Deben analizarse los vicios y defensas que puedan acreditarse.'),
choice('Entendé el blanco','¿Qué permite el endoso en blanco?',['Transmitir por entrega sin completar el endoso, entre otras opciones legales','Eliminar la firma de Marco','Convertir todos los pagarés en cheques'],0,'El art. 15 ofrece varias posibilidades.','Se permite llenar el blanco, volver a endosar o transmitir sin llenarlo. El instrumento sigue siendo un pagaré a la orden.'),
choice('Separá sospecha y prueba','Si se prueba que Bruno no firmó, ¿qué afirmación es correcta?',['Bruno responde por la firma falsa de todas formas','Todas las firmas auténticas se vuelven nulas','Bruno no se obliga por esa firma falsa; las obligaciones de otros firmantes pueden subsistir'],2,'El art. 7 trata la independencia de las firmas.','No se imputa a Bruno una firma falsa. Las firmas auténticas no pierden automáticamente validez. La legitimación y buena fe del portador requieren análisis propio.'),
choice('Distinguí acciones','¿Cómo se organiza el análisis contra Marco y los endosantes?',['Acción directa contra el suscriptor y regreso contra endosantes si se conservó','Solo se puede reclamar contra Ana','Primero siempre debe ejecutarse todo el patrimonio de Marco para recién pensar en otro firmante'],0,'Las acciones tienen sujetos y recaudos diferentes.','Marco es suscriptor y obligado principal. El regreso contra endosantes tiene cargas específicas; no se describe simplemente como una garantía civil subsidiaria.')],
'Explicá por qué una firma falsa no resuelve por sí sola todo el caso.',
'Hay que separar quién firmó auténticamente, quién posee y cómo se legitima, qué defensas son oponibles y qué acciones se conservaron. La firma falsa de Bruno no invalida automáticamente las demás.'),
C('tc03','5.000 en números, 5.500 en letras','Títulos de crédito','titulos','diapositiva 6',
'Un pagaré firmado indica $5.000 en cifras y “cinco mil quinientos” en letras. El material pregunta qué importe obliga.',
'Se aplica la regla argentina concreta de los arts. 6 y 103. El supuesto inicial no incluye alteración; luego se agrega esa variante expresamente.',[['letras','arts. 6, 88 y 103']], [
choice('Elegí la regla','Ante la diferencia simple entre letras y cifras, ¿qué prevalece?',['Siempre la suma menor','La suma en letras','La que prefiera el acreedor'],1,'No confundas dos hipótesis diferentes del art. 6.','Cuando hay una suma en letras y otra en cifras, prevalece la expresada en letras.'),
number('Aplicá','Sin alteración acreditada, ¿cuál es el importe?',5500,'pesos','Leé “cinco mil quinientos”.','La respuesta es 5.500. La regla de la suma menor corresponde a otra hipótesis de repetición de importes.'),
choice('Variante','Si se prueba que las letras fueron alteradas después, ¿alcanza repetir “siempre valen las letras”?',['Sí','Sí, si el papel es original','No: hay que analizar la alteración y el momento de cada firma'],2,'El art. 88 distingue firmantes anteriores y posteriores.','La regla de discrepancia no sustituye al régimen de alteración del título.')],
'Diferenciá discrepancia de importes y alteración del documento.',
'La discrepancia simple se resuelve con la regla del art. 6. Una alteración acreditada exige revisar el art. 88 y los términos que obligan a cada firmante.'),
C('tc04','“Te pago si el negocio prospera”','Títulos de crédito','titulos','diapositiva 7',
'Se firma un pagaré por $10.000. Hubo un acuerdo oral previo que supeditaba el pago al éxito del negocio. El beneficiario original exige el total.',
'El material mezcla beneficiario original y tercero protegido. La actividad obliga a distinguirlos y evita afirmar que toda defensa causal es imposible en cualquier proceso.',[['letras','arts. 18 y 101–103']], [
choice('Detectá la distinción','¿Qué dato importa antes de responder sobre la condición oral?',['Quién reclama: beneficiario original o tercero','Si el papel es blanco','Si el deudor recuerda el monto'],0,'El art. 18 habla de relaciones con tenedores anteriores.','No es lo mismo discutir entre partes inmediatas que frente a un tercero protegido por la circulación.'),
choice('Elegí una respuesta cuidadosa','Entre partes inmediatas, ¿la literalidad borra toda discusión causal en cualquier vía?',['Sí','No: deben examinarse defensas y límites de la vía procesal','Sí, si no hay testigos'],1,'Separá derecho sustancial y proceso ejecutivo.','Las restricciones de un proceso ejecutivo no equivalen a afirmar que la relación causal nunca puede discutirse.'),
choice('Variante escrita','Si la promesa del propio pagaré dijera “pagaré solo si prospera el negocio”, ¿qué requisito se compromete?',['La promesa pura y simple','El color de la tinta','La cantidad de endosos'],0,'Ahora la condición está en el título, no solo en un pacto oral.','El art. 101 exige una promesa incondicionada de pagar una suma determinada. Esa variante requiere un análisis distinto.')],
'Respondé diferenciando pacto oral, condición en el título y tercero.',
'Primero identificaría al reclamante y la vía. El pacto oral entre partes inmediatas no se analiza igual que una defensa contra un tercero. Una condición inserta en la promesa afecta un requisito del pagaré.'),
C('tc05','Ana entrega un cheque a Carlos','Títulos de crédito','titulos','diapositivas 9–10',
'Ana Martínez paga a Carlos López un servicio por 1.200 dólares con un cheque contra Banco Azul. Carlos lo presenta y el banco debe verificar su pago.',
'El modelo original usa Madrid y fecha 08/28/2025. Para aplicar Ley 24.452 se propone expresamente una variante: cheque común de una cuenta en dólares y pago en Argentina, emitido el 28/08/2025. Se conservan sujetos e importe.',[['cheques','arts. 1–2, 23, 25, 38 y 40']], [
choice('Reconocé al girado','¿Quién recibe la orden de pago?',['Carlos','Ana','Banco Azul'],2,'El banco es el girado del cheque.','Ana libra, Banco Azul recibe la orden y Carlos es el beneficiario.'),
choice('Ubicá la exigibilidad','En la variante de cheque común, ¿cómo es pagadero?',['A la vista','Siempre a seis meses','Cuando Ana cambie de opinión'],0,'No lo confundas con el cheque de pago diferido.','El cheque común es pagadero a la vista, conforme a las reglas de presentación.'),
choice('Ante el rechazo','Si no se paga por falta de fondos, ¿el banco queda automáticamente obligado como aceptante cambiario?',['Sí','No: hay que documentar el rechazo y analizar acciones contra los obligados','Sí, por aparecer su nombre'],1,'El cheque no se acepta como una letra de cambio.','El rechazo habilita el análisis de las acciones correspondientes, con sus recaudos. Una eventual responsabilidad del banco requiere fundamento propio.')],
'Armá la secuencia de cobro e identificá el documento importante si se rechaza.',
'Entrega del cheque, presentación en término y pago o rechazo documentado. Luego se examinan las acciones y sus plazos. No se presume aceptación cambiaria del banco.'),
C('tc06','María promete pagarle a Luis','Títulos de crédito','titulos','diapositiva 14',
'El 28/08/2025 María Pérez recibe de Luis Gómez 5.000 dólares y firma un pagaré a su orden, con vencimiento el 28/02/2026 y pago en una oficina de Ciudad X.',
'Se normaliza el formato de las fechas del modelo, manteniendo sus valores. Ciudad X se conserva como lugar del ejemplo, sin afirmar que el modelo sea un formulario listo para usar.',[['letras','arts. 35, 101–104']], [
choice('Identificá roles','¿Quién asume la obligación principal del pagaré?',['Luis como beneficiario','María como suscriptora','Un banco no mencionado'],1,'Firma quien promete pagar.','María es suscriptora. No hace falta un girado que acepte como en la letra de cambio.'),
choice('Leé el vencimiento','¿Qué fecha aparece como vencimiento?',['28/08/2025','28/02/2026','No hay fecha de pago'],1,'Separá creación y vencimiento.','El título indica día fijo: 28/02/2026. La creación ocurrió seis meses antes.'),
choice('Variante de omisión','Si se omitiera el vencimiento, manteniendo los demás requisitos, ¿qué suplencia aplica?',['Se vuelve cheque','Vale por diez años sin posibilidad de cobro','Se considera pagable a la vista'],2,'El art. 102 contempla esta omisión.','La falta de vencimiento tiene suplencia legal. No toda omisión invalida del mismo modo.')],
'¿Qué revisarías además de importe y fecha antes de afirmar validez formal?',
'Denominación o cláusula a la orden, promesa pura y simple, beneficiario, lugar y fecha de creación, lugar de pago y firma, con las suplencias y excepciones efectivamente aplicables.'),
C('ta01','Laboratorio de modelos de documentos','Taller documental','titulos','diapositivas 11, 15 y 19',
'La presentación muestra un cheque bancario de Madrid, un pagaré de Lima y un formulario de letra de cambio sin completar. Este taller trabaja su lectura sin reproducir firmas, números bancarios ni las imágenes.',
'Son modelos de distintos contextos. Reconocer campos no acredita validez bajo derecho argentino. Los datos de práctica se limitan a lo visible y a variantes explícitas.',[['letras','arts. 1–2 y 101–104'],['cheques','arts. 1–2']], [
choice('Leé el contexto','¿Un cheque de Madrid o un pagaré de Lima demuestra que el mismo formulario sirve sin cambios en Argentina?',['Sí','No: hay que determinar la ley y los requisitos aplicables','Sí, si está en español'],1,'Idioma y ley aplicable no son equivalentes.','Se puede practicar lectura de campos sin trasladar automáticamente reglas extranjeras.'),
choice('Leé la letra','¿Qué efecto tiene la aceptación del girado en una letra?',['Lo obliga cambiariamente como aceptante','Cambia el beneficiario por el banco','Elimina al librador del documento'],0,'La aceptación es un acto propio de la letra.','Identificar girado no equivale a afirmar que ya aceptó. La aceptación genera su obligación cambiaria.'),
choice('Detectá el límite','¿Un formulario en blanco permite afirmar que existe una obligación válida por un monto concreto?',['Sí, por tener líneas para firmar','Sí, por decir “letra”','No: faltan contenido, firmas y contexto'],2,'Un modelo no es un título efectivamente completado y emitido.','Hay que revisar el instrumento concreto, sus requisitos y actos. No inventamos montos ni sujetos que el formulario no contiene.')],
'Prepará una lista para revisar un documento antes de confiar en su apariencia.',
'Identificar tipo y ley aplicable, leer sujetos, importe, fechas y lugares, verificar firmas y actos de circulación, y distinguir campos vacíos de datos efectivamente incorporados.','workshop'),
C('ta02','Auditoría de requisitos y suplencias','Taller documental','actividad','PDF pp. 1–3; UNIDAD 2, requisitos y comparación',
'La consigna de UNIDAD 2 pide verificar requisitos y suplencias del pagaré, compararlos con la letra de cambio y enfocarse en los sujetos. El PDF desarrolla esa comparación.',
'Correcciones expresas: la tabla del PDF intercambia algunas columnas; el art. 102 argentino no contempla la suplencia del lugar de creación del pagaré que sí se describe para la letra en el art. 2. Se trabaja el pagaré común, no la excepción especial de negociación en mercados CNV.',[['letras','arts. 1–2 y 101–104']], [
multiple('Auditá requisitos','En un pagaré común ya completo para ejercer el derecho, ¿qué ausencias no tienen la suplencia invocada en el material?',['Firma del suscriptor','Fecha de creación','Lugar de creación','Plazo de pago'],[0,1,2],'Leé las dos suplencias efectivamente enumeradas por el art. 102.','El art. 102 contempla falta de plazo y falta de lugar de pago. No incorpora una suplencia del lugar de creación como la de la letra. Se distingue de completar un título en blanco bajo sus reglas.'),
choice('Aplicá una suplencia real','Si falta indicación especial del lugar de pago del pagaré, ¿qué lugar se toma?',['El de creación del título','El que prefiera el beneficiario','Siempre el domicilio del girado'],0,'El pagaré no necesita girado.','El lugar de creación funciona como lugar de pago y domicilio del suscriptor, según el art. 102.'),
choice('Compará sujetos','¿Qué diferencia está bien formulada?',['El pagaré contiene una orden al girado; la letra una promesa del suscriptor','El pagaré contiene la promesa del suscriptor; la letra una orden al girado','Ambos requieren un banco aceptante'],1,'Yo prometo pagar versus ordeno a otro que pague.','En la letra el girado se obliga cambiariamente como aceptante cuando acepta. En el pagaré el suscriptor es obligado principal.'),
choice('Evitá otra generalización','¿Un pagaré común puede omitir libremente al beneficiario por llamarse “al portador”?',['Sí, siempre','No: no debe generalizarse la excepción específica del art. 101','Sí, si alguien lo endosa después'],1,'La excepción de mercado no define el pagaré común.','El art. 101 exige beneficiario salvo el supuesto especial que regula para ciertos pagarés negociados en mercados registrados. Un endoso en blanco posterior es otra cuestión.')],
'Compará las suplencias de ambos títulos sin copiar la tabla mecánicamente.',
'En ambos, falta de vencimiento conduce a pago a la vista. En el pagaré, falta de lugar de pago remite al de creación. En la letra, el art. 2 prevé además reglas específicas ligadas al girado y al librador. No se trasladan automáticamente al pagaré.','workshop')
];

export const CASES=[...WORD_CASES,...EXTRA_CASES.map(c=>({...c,collection:"extra"}))];
